//! The certificate parser, graded against `openssl x509 -text` over the same
//! bytes.
//!
//! The fixture is a real certificate (`tests/fixtures/lab_certificate.der`,
//! generated by `scripts/make-tls-fixtures.sh`), and every expectation below
//! is the number or string OpenSSL prints for it:
//!
//! ```text
//! Serial Number: 3b:da:c8:35:96:65:e6:fe:6d:a6:9c:6a:4b:bf:38:a0:16:fd:84:6b
//! Signature Algorithm: sha256WithRSAEncryption
//! Issuer:  C=IE, ST=Dublin, O=Seance Lab, OU=Forensics, CN=lab.seance.invalid
//! Subject: C=IE, ST=Dublin, O=Seance Lab, OU=Forensics, CN=lab.seance.invalid
//! Not Before: Sep 15 21:21:47 2026 GMT
//! Not After : Sep 12 21:21:47 2036 GMT
//! Public-Key: (2048 bit) rsaEncryption
//! X509v3 Basic Constraints: critical CA:TRUE
//! X509v3 Subject Alternative Name:
//!     DNS:lab.seance.invalid, DNS:alt.seance.invalid, IP Address:127.0.0.1
//! sha256 Fingerprint=E0:E0:BC:2F:EE:38:69:7C:25:5D:A4:B4:11:5D:EF:0A:
//!                    57:02:B7:B9:DD:05:06:6D:80:1C:09:E8:62:CA:87:5A
//! ```

use super::*;

const LAB: &[u8] = include_bytes!("../tests/fixtures/lab_certificate.der");

#[test]
fn the_names_dates_and_key_are_what_openssl_reads_from_the_same_bytes() {
    let cert = Certificate::parse(LAB).expect("a certificate");
    assert_eq!(cert.version, 3);
    assert_eq!(cert.serial_hex, "3bdac8359665e6fe6da69c6a4bbf38a016fd846b");
    assert_eq!(cert.signature_algorithm, "sha256WithRSAEncryption");
    assert_eq!(
        cert.subject,
        "C=IE, ST=Dublin, O=Seance Lab, OU=Forensics, CN=lab.seance.invalid"
    );
    assert_eq!(cert.issuer, cert.subject);
    assert_eq!(
        cert.subject_common_name.as_deref(),
        Some("lab.seance.invalid")
    );
    assert_eq!(cert.subject_organisation.as_deref(), Some("Seance Lab"));
    assert_eq!(
        cert.issuer_common_name.as_deref(),
        Some("lab.seance.invalid")
    );
    assert_eq!(cert.not_before.as_deref(), Some("2026-09-15T21:21:47Z"));
    assert_eq!(cert.not_after.as_deref(), Some("2036-09-12T21:21:47Z"));
    assert_eq!(cert.key_algorithm.as_deref(), Some("rsaEncryption"));
    assert_eq!(cert.key_bits, Some(2048));
    assert_eq!(cert.is_certificate_authority, Some(true));
    assert_eq!(
        cert.sha256,
        "e0e0bc2fee38697c255da4b4115def0a5702b7b9dd05066d801c09e862ca875a"
    );
}

/// **The names a certificate claims are the reason to read one.** All of them,
/// in the order they were sent, and each under the kind of name it is: a `DNS`
/// entry and an `IP` entry are different claims.
#[test]
fn every_subject_alternative_name_is_read_under_its_own_kind() {
    let cert = Certificate::parse(LAB).expect("a certificate");
    assert_eq!(
        cert.dns_names,
        vec!["lab.seance.invalid", "alt.seance.invalid"]
    );
    assert_eq!(cert.ip_addresses, vec!["127.0.0.1"]);
    assert!(cert.email_addresses.is_empty());
    assert!(cert.uris.is_empty());
    // The names an examiner searches: the CN and every SAN, deduplicated, and
    // the CN is not assumed to be among the SANs.
    assert_eq!(
        cert.names(),
        vec!["lab.seance.invalid", "alt.seance.invalid", "127.0.0.1"]
    );
}

/// **A certificate that signed itself says so, and that is all it says.**
/// Self-signed is a fact about the two names; it is not a verdict, and this
/// build verifies no signature and builds no chain.
#[test]
fn a_self_signed_certificate_is_named_as_one_without_a_verdict_being_implied() {
    let cert = Certificate::parse(LAB).expect("a certificate");
    assert!(cert.self_signed);
    let json = cert.to_json();
    assert_eq!(json["self_signed"], serde_json::json!(true));
    assert_eq!(
        json["signature_verified"],
        serde_json::json!(false),
        "the field exists and is false: an absent field reads as a verified one"
    );
    assert!(json["statement"]
        .as_str()
        .is_some_and(|s| s.contains("NOT verified")));
}

/// An extension this build does not read is still on the record, by its OID,
/// because the OID is the evidence and "unknown" is not.
#[test]
fn an_extension_this_build_does_not_read_is_recorded_by_its_oid() {
    let cert = Certificate::parse(LAB).expect("a certificate");
    // Subject and authority key identifiers are in this certificate and are
    // not fields of their own here.
    assert!(
        cert.extensions.iter().any(|e| e.oid == "2.5.29.14"),
        "{:?}",
        cert.extensions
    );
    let critical: Vec<&str> = cert
        .extensions
        .iter()
        .filter(|e| e.critical)
        .map(|e| e.name.as_str())
        .collect();
    assert_eq!(critical, vec!["basicConstraints"]);
}

// ── What it refuses ─────────────────────────────────────────────────────────

/// Bytes that are not a certificate are refused rather than half-read. Every
/// prefix of a real one is refused too: a certificate read from a truncated
/// DER would carry fields nobody signed.
#[test]
fn truncated_and_foreign_bytes_are_refused() {
    assert!(Certificate::parse(b"").is_none());
    assert!(Certificate::parse(b"MZ\x90\x00 not a certificate").is_none());
    assert!(Certificate::parse(&LAB[..LAB.len() / 2]).is_none());
    // A SEQUENCE whose declared length runs past the buffer.
    assert!(Certificate::parse(&[0x30, 0x82, 0x0f, 0xff, 0x00]).is_none());
}

/// A length that would overflow the cursor's arithmetic, and a nesting depth
/// that would overflow the stack, are refused rather than followed.
#[test]
fn a_hostile_length_or_depth_is_refused_not_followed() {
    // A definite length of eight full bytes: 0xFFFFFFFFFFFFFFFF.
    let mut hostile = vec![0x30, 0x88];
    hostile.extend_from_slice(&[0xff; 8]);
    assert!(Certificate::parse(&hostile).is_none());
    // DER has no indefinite length; BER's is refused rather than guessed at.
    assert!(Certificate::parse(&[0x30, 0x80, 0x00, 0x00]).is_none());
    // Nested SEQUENCEs all the way down.
    let mut deep = Vec::new();
    for _ in 0..512 {
        deep.extend_from_slice(&[0x30, 0x7f]);
    }
    assert!(Certificate::parse(&deep).is_none());
}

// ── Bytes an attacker chose ─────────────────────────────────────────────────

/// **A validity time is attacker-controlled bytes, and reading it must not
/// panic.** The first version of this parser sliced the time as a `&str` at
/// fixed offsets: a multi-byte character inside it put a slice boundary in the
/// middle of a code point, which panics — and a panic here would take the
/// whole capture's parse with it.
#[test]
fn a_time_field_of_hostile_bytes_is_refused_rather_than_panicking() {
    // A UTCTime whose thirteen bytes are a three-byte euro sign, nine digits
    // and the Z: valid UTF-8, twelve bytes before the Z, and byte offset 2
    // falls inside the euro sign.
    let mut hostile = vec![0x17, 0x0d];
    hostile.extend_from_slice("€123456789Z".as_bytes());
    assert!(
        validity_for_test(&hostile).is_none(),
        "hostile time bytes are refused"
    );
    // And a few more shapes that must all refuse rather than guess.
    for contents in [
        "2601011200Z".as_bytes(),       // too short
        "260101120000+0100".as_bytes(), // an offset RFC 5280 forbids
        "26AB01120000Z".as_bytes(),     // not digits
        "261301120000Z".as_bytes(),     // month 13
        "260132120000Z".as_bytes(),     // day 32
        "260101250000Z".as_bytes(),     // hour 25
        &[0xff, 0xfe, 0x00],            // not UTF-8 at all
    ] {
        let mut der = vec![0x17, contents.len() as u8];
        der.extend_from_slice(contents);
        assert!(
            validity_for_test(&der).is_none(),
            "{:?} must be refused",
            String::from_utf8_lossy(contents)
        );
    }
    // The ordinary form still reads.
    let mut good = vec![0x17, 0x0d];
    good.extend_from_slice(b"260915212147Z");
    assert_eq!(
        validity_for_test(&good).as_deref(),
        Some("2026-09-15T21:21:47Z")
    );
    // And the year pivot RFC 5280 specifies.
    let mut old = vec![0x17, 0x0d];
    old.extend_from_slice(b"990915212147Z");
    assert_eq!(
        validity_for_test(&old).as_deref(),
        Some("1999-09-15T21:21:47Z")
    );
}

/// **A genuinely nested DER is refused, and there is no depth bound to be
/// refused by.** The first version of this test built 512 *sibling* TLVs and
/// claimed to prove depth-refusal; the trailing-bytes check refused them
/// before the walk ever nested, and the depth guard it named was unreachable
/// code — the walk is not recursive, so it has been removed rather than left
/// implying a protection it never gave. What actually holds is this: every
/// member is a slice of its parent, so a nest of any depth is refused as soon
/// as a level is not the structure a certificate has.
#[test]
fn a_genuinely_nested_der_is_refused_without_recursing() {
    // Innermost: an empty SEQUENCE. Then wrap it, with a correct length, six
    // hundred times — far deeper than any real certificate.
    let mut der = vec![0x30, 0x00];
    for _ in 0..600 {
        let mut outer = vec![0x30];
        outer.extend_from_slice(&der_length(der.len()));
        outer.extend_from_slice(&der);
        der = outer;
    }
    // The outermost length covers the whole buffer, so the trailing-bytes
    // check passes and the walk is forced inward.
    let (tag, total) = super::tlv_for_test(&der).expect("a TLV");
    assert_eq!(tag, 0x30);
    assert_eq!(total, der.len(), "the outer length covers the buffer");
    assert!(
        Certificate::parse(&der).is_none(),
        "a nest this deep is refused, and refusing it does not recurse"
    );
    // A thousand siblings at one level are refused by the count bound rather
    // than walked.
    let mut siblings = Vec::new();
    for _ in 0..2_000 {
        siblings.extend_from_slice(&[0x30, 0x00]);
    }
    assert!(Certificate::parse(&der_sequence(&siblings)).is_none());
}

/// **A name list cut by the ceiling is a prefix, and says so.** The name an
/// examiner is looking for may be the one past the cut, so a `false` answer to
/// "does this certificate cover that name" must not be given from a truncated
/// list.
#[test]
fn alternative_names_past_the_ceiling_are_counted_and_the_list_says_it_is_a_prefix() {
    let der = certificate_with_many_names(MAX_NAMES + 12);
    let cert = Certificate::parse(&der).expect("a certificate");
    assert_eq!(cert.dns_names.len(), MAX_NAMES);
    assert_eq!(cert.names_beyond_cap, 12);
    let json = cert.to_json();
    assert_eq!(json["names_beyond_cap"], serde_json::json!(12));
    assert_eq!(json["names_are_complete"], serde_json::json!(false));
    let (reason, detail) = cert
        .shortfalls()
        .into_iter()
        .find(|(_, d)| d.contains("PREFIX"))
        .expect("the cut is a shortfall");
    assert_eq!(reason, seance_core::io::IncompleteReason::CapReached);
    assert!(
        detail.contains("may still be in the certificate"),
        "{detail}"
    );
}

/// A certificate carrying `count` DNS names, built field by field so the
/// only thing the assertions depend on is what this fixture placed. The real
/// certificate in `tests/fixtures` is what grades the field reading; this
/// grades the ceiling.
fn certificate_with_many_names(count: usize) -> Vec<u8> {
    let mut names = Vec::new();
    for n in 0..count {
        let name = format!("host{n}.example.invalid");
        names.push(0x82);
        names.push(name.len() as u8);
        names.extend_from_slice(name.as_bytes());
    }
    let mut extension = Vec::new();
    // OID 2.5.29.17 subjectAltName, then the GeneralNames inside an OCTET
    // STRING, which is how an extension's value is carried.
    extension.extend_from_slice(&[0x06, 0x03, 0x55, 0x1d, 0x11]);
    extension.extend_from_slice(&der_octet_string(&der_sequence(&names)));
    minimal_certificate(&der_sequence(&der_sequence(&extension)))
}

/// A structurally complete certificate with the given extensions block.
fn minimal_certificate(extensions: &[u8]) -> Vec<u8> {
    let mut tbs = Vec::new();
    // [0] EXPLICIT version 3 (encoded as 2).
    tbs.extend_from_slice(&[0xa0, 0x03, 0x02, 0x01, 0x02]);
    // serialNumber
    tbs.extend_from_slice(&[0x02, 0x01, 0x2a]);
    // signature AlgorithmIdentifier: sha256WithRSAEncryption
    tbs.extend_from_slice(&der_sequence(&[
        0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b,
    ]));
    // issuer and subject: CN=fixture
    let name = der_sequence(&der_set(&der_sequence(
        &[&[0x06, 0x03, 0x55, 0x04, 0x03][..], &der_utf8("fixture")].concat(),
    )));
    tbs.extend_from_slice(&name);
    // validity
    let mut validity = Vec::new();
    for stamp in [b"260101000000Z", b"360101000000Z"] {
        validity.push(0x17);
        validity.push(stamp.len() as u8);
        validity.extend_from_slice(stamp);
    }
    tbs.extend_from_slice(&der_sequence(&validity));
    tbs.extend_from_slice(&name);
    // subjectPublicKeyInfo: an rsaEncryption algorithm and a token key.
    let spki_algorithm = der_sequence(&[
        0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01, 0x05, 0x00,
    ]);
    let mut key = vec![0x00];
    key.extend_from_slice(&der_sequence(
        &[&[0x02, 0x02, 0x00, 0x81][..], &[0x02, 0x01, 0x03][..]].concat(),
    ));
    let mut bit_string = vec![0x03];
    bit_string.extend_from_slice(&der_length(key.len()));
    bit_string.extend_from_slice(&key);
    tbs.extend_from_slice(&der_sequence(
        &[spki_algorithm.as_slice(), bit_string.as_slice()].concat(),
    ));
    // [3] EXPLICIT extensions
    let mut explicit = vec![0xa3];
    explicit.extend_from_slice(&der_length(extensions.len()));
    explicit.extend_from_slice(extensions);
    tbs.extend_from_slice(&explicit);

    let mut certificate = der_sequence(&tbs);
    // The signatureAlgorithm and signatureValue, which this build reads the
    // first of and never verifies.
    let mut rest = der_sequence(&[
        0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b,
    ]);
    rest.extend_from_slice(&[0x03, 0x05, 0x00, 0xde, 0xad, 0xbe, 0xef]);
    let mut inner = certificate.clone();
    inner.extend_from_slice(&rest);
    certificate = der_sequence(&inner[..]);
    certificate
}

fn der_set(contents: &[u8]) -> Vec<u8> {
    let mut out = vec![0x31];
    out.extend_from_slice(&der_length(contents.len()));
    out.extend_from_slice(contents);
    out
}

fn der_utf8(text: &str) -> Vec<u8> {
    let mut out = vec![0x0c];
    out.extend_from_slice(&der_length(text.len()));
    out.extend_from_slice(text.as_bytes());
    out
}

fn der_length(length: usize) -> Vec<u8> {
    if length < 0x80 {
        vec![length as u8]
    } else if length <= 0xff {
        vec![0x81, length as u8]
    } else {
        vec![0x82, (length >> 8) as u8, (length & 0xff) as u8]
    }
}

fn der_sequence(contents: &[u8]) -> Vec<u8> {
    let mut out = vec![0x30];
    out.extend_from_slice(&der_length(contents.len()));
    out.extend_from_slice(contents);
    out
}

fn der_octet_string(contents: &[u8]) -> Vec<u8> {
    let mut out = vec![0x04];
    out.extend_from_slice(&der_length(contents.len()));
    out.extend_from_slice(contents);
    out
}
